/* crosswalk cards, r29. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29a"]=[{"q": "Without the parallel axiom, how does an outside angle of a triangle compare with each inside angle away from it?", "a": "it is larger", "w": ["it is equal to their sum", "it is smaller", "it can be either"], "why": "The outside-angle technique: a part of the outside angle already equals the far angle."}, {"q": "Which technique licenses ∠ACD > ∠BAC, when a part of ∠ACD equals ∠BAC?", "a": "the outside-angle technique", "w": ["the top-angles technique", "the parallel-through-a-point technique", "the side-side-side technique"], "why": "A part of the outside angle equals ∠BAC; the whole is larger."}, {"q": "Two lines at right angles to the same line. Without the parallel axiom, what follows?", "a": "they never meet", "w": ["they meet on one side", "they stay the same distance apart", "nothing can be said"], "why": "The never-meet technique: meeting would make a right angle larger than a right angle."}, {"q": "Of the parallel axiom’s “at least one” and “at most one”, which do the other axioms already give?", "a": "at least one", "w": ["at most one", "both", "neither"], "why": "Two right angles build a line that never meets. At most one is the whole question."}, {"q": "An upright figure has equal uprights at right angles to its base. What do the other axioms give about its top angles?", "a": "they are equal", "w": ["they are right", "they are sharp", "they add to π"], "why": "The top-angles technique: side-angle-side, then side-side-side."}, {"q": "Without the parallel axiom, the angles of every triangle add to …", "a": "at most π", "w": ["exactly π", "less than π", "more than π"], "why": "The no-more-than-straight technique, by the halving move."}, {"q": "The halving move turns a triangle into another. What stays the same?", "a": "the angle sum", "w": ["the area", "the three angles", "the longest side"], "why": "The two pieces of ∠A go to two corners; the angle at C gains ∠ABC."}, {"q": "Top angles of 95° in an upright figure would give the figure’s angles a total of …", "a": "370°, more than the 360° allowed", "w": ["360°, as allowed", "350°, as allowed", "190°"], "why": "Two triangles of at most π each: blunt top angles are refuted."}, {"q": "Which case of the top angles was left open after 1733?", "a": "sharp", "w": ["right", "blunt", "none"], "why": "Blunt is refuted; the parallel axiom gives right; sharp had no false line."}, {"q": "Accepted name for the top angles of an upright figure?", "a": "the summit angles", "w": ["the base angles", "the exterior angles", "the vertical angles"], "why": "The figure has a base, two legs and a summit."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29b"]=[{"q": "On a sphere, what are the lines?", "a": "great circles, whose planes pass through the centre", "w": ["circles of latitude", "any circle on the sphere", "meridians only"], "why": "Lines of the sphere are cut by planes through O."}, {"q": "Two different great circles meet in …", "a": "exactly two opposite points", "w": ["one point", "no points, if their normals are parallel", "endlessly many points"], "why": "The lines-always-meet technique: the planes meet in a line through O."}, {"q": "Which technique licenses: the two planes meet along x = t(n₁ × n₂)?", "a": "the cross technique (27i)", "w": ["the lune-area technique", "the excess-area technique", "the angle-between technique"], "why": "n₁ × n₂ is at right angles to both normals and is not 0."}, {"q": "A lune of angle α on a sphere of radius R has area …", "a": "2αR²", "w": ["αR²", "4αR²", "α R²/2"], "why": "The lune-area technique: α/2π of the skin 4πR²."}, {"q": "The lune between 120° W and 90° W is what share of the earth?", "a": "one twelfth", "w": ["one sixth", "one quarter", "one twenty-fourth"], "why": "Its angle is π/6, and (π/6)/(2π) = 1/12."}, {"q": "A triangle on a sphere has angles α, β, γ. Its area is …", "a": "(α + β + γ − π)R²", "w": ["(α + β + γ)R²", "(π − α − β − γ)R²", "½(α + β + γ)R²"], "why": "The excess-area technique, from three pairs of lunes."}, {"q": "The North Pole and the equator at 0° and 90° E make a triangle with angles …", "a": "90°, 90°, 90°", "w": ["90°, 45°, 45°", "60°, 60°, 60°", "90°, 90°, 0°"], "why": "Its excess is π/2: one eighth of the skin."}, {"q": "A triangle of mountain tops 100 km apart on the earth has an excess of about …", "a": "22 seconds of arc", "w": ["22 degrees", "one second of arc", "zero"], "why": "4300/6371² radians is about 1.06 × 10⁻⁴ radians."}, {"q": "Can two triangles on one sphere have the same angles and different areas?", "a": "no", "w": ["yes, if one is an enlargement", "yes, if they are far apart", "only for small triangles"], "why": "The same-angles-same-size technique: the excess fixes the area."}, {"q": "Accepted name for the slice between two great circles?", "a": "a lune", "w": ["a sector", "a cap", "a zone"], "why": "Also a digon, or spherical biangle."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29c"]=[{"q": "What are the points of the disc plane?", "a": "the z with |z| < 1", "w": ["the z with |z| ≤ 1", "the whole plane", "the unit circle"], "why": "The edge |z| = 1 is not part of it."}, {"q": "What are the lines of the disc plane?", "a": "diameters, and arcs of circles meeting the edge at right angles", "w": ["straight chords", "every circle inside the disc", "circles through 0"], "why": "A circle meets the edge at right angles when |c|² = 1 + r²."}, {"q": "With a = ½, fₐ(z) = (z − ½)/(1 − ½z). What is fₐ(0)?", "a": "−½", "w": ["½", "0", "−2"], "why": "(0 − ½)/(1 − 0) = −½."}, {"q": "Which technique licenses: |z| < 1 exactly when |fₐ(z)| < 1?", "a": "the disc-moves technique", "w": ["the one-line technique", "the many-parallels technique", "the below-straight technique"], "why": "From |1 − p̄z|² − |z − p|² = (1 − |z|²)(1 − |a|²)."}, {"q": "Why do only diameters pass through 0 in the disc plane?", "a": "|c|² = 1 + r² > r², so 0 is never on such a circle", "w": ["circles are not lines", "0 is on the edge", "arcs are too short"], "why": "The distance from 0 to c is more than r."}, {"q": "Through a point off a line of the disc plane pass how many lines that never meet it?", "a": "endlessly many", "w": ["exactly one", "none", "exactly two"], "why": "The many-parallels technique: a whole fan of diameters, after a move."}, {"q": "The triangle 0, ½, i/2 in the disc plane has angles adding to about …", "a": "152°", "w": ["180°", "90°", "200°"], "why": "90° at 0, about 31° at each of the others."}, {"q": "Why can the other axioms not refute the parallel axiom?", "a": "ℝ² obeys the other axioms and the parallel statement", "w": ["the disc plane obeys them", "no one has tried", "the parallel axiom is true"], "why": "A refutation would hold in ℝ², where the parallel statement is proved (18c)."}, {"q": "Why can the other axioms not prove the parallel axiom?", "a": "the disc plane obeys them and the parallel axiom fails there", "w": ["the sphere obeys them", "ℝ² obeys them", "the proof would be too long"], "why": "A proof from axioms holds wherever the axioms hold."}, {"q": "Accepted name for the geometry of the disc plane?", "a": "hyperbolic geometry", "w": ["elliptic geometry", "spherical geometry", "projective geometry"], "why": "Geometry with the other axioms alone is neutral geometry."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29d"]=[{"q": "On a patch r(u, v), what is F?", "a": "r<sub>u</sub> · r<sub>v</sub>", "w": ["r<sub>u</sub> · r<sub>u</sub>", "|r<sub>u</sub> × r<sub>v</sub>|", "r<sub>v</sub> · r<sub>v</sub>"], "why": "E = r<sub>u</sub> · r<sub>u</sub>, F = r<sub>u</sub> · r<sub>v</sub>, G = r<sub>v</sub> · r<sub>v</sub>."}, {"q": "Why does the ruler have 2F du dv and not F du dv?", "a": "r<sub>u</sub> · r<sub>v</sub> and r<sub>v</sub> · r<sub>u</sub> both appear", "w": ["F is always doubled by convention", "the curve is traced twice", "du and dv are equal"], "why": "The dot product spreads over the sum u′r<sub>u</sub> + v′r<sub>v</sub>."}, {"q": "The length of a curve on a patch is ∫ of …", "a": "√(E u′² + 2F u′v′ + G v′²)", "w": ["E u′² + 2F u′v′ + G v′²", "E u′ + 2F + G v′", "√(EG − F²)"], "why": "The ruler-length technique: distance is the total of speed."}, {"q": "Which technique licenses: area = ∬ √(EG − F²) du dv?", "a": "the ruler-area technique", "w": ["the ruler-length technique", "the ruler-change technique", "the change-of-variables technique"], "why": "|r<sub>u</sub> × r<sub>v</sub>|² = EG − F², then 28n."}, {"q": "For the sphere in latitude φ and longitude λ, what is G?", "a": "R² cos² φ", "w": ["R²", "R² sin² φ", "R cos φ"], "why": "A step dλ runs along a circle of radius R cos φ."}, {"q": "One degree of longitude at the top of the Salish Sea (50.1° N) is about …", "a": "71 km", "w": ["111 km", "54 km", "90 km"], "why": "111.2 km × cos 50.1°."}, {"q": "Changing coordinates by a map with slope grid J turns the ruler grid g into …", "a": "Jᵀ g J", "w": ["J g", "g J", "J⁻¹ g J"], "why": "The ruler-change technique: dot products of mixes."}, {"q": "The flat plane in round measures has ruler …", "a": "dρ² + ρ² dθ²", "w": ["dρ² + dθ²", "dρ² + ρ dθ²", "ρ²(dρ² + dθ²)"], "why": "Jᵀ J = diag(1, ρ²)."}, {"q": "In the disc plane, how far is the point 0.9 from 0?", "a": "ln 19, about 2.94", "w": ["0.9", "ln 1.9", "about 1.10"], "why": "d(0, ρ) = ln((1 + ρ)/(1 − ρ))."}, {"q": "Accepted name for the ruler?", "a": "the metric, or first fundamental form", "w": ["the second fundamental form", "the Jacobian", "the curvature"], "why": "ds² is the line element."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29e"]=[{"q": "A circle of radius 250 m on a highway. What is its bend?", "a": "1/250 per metre", "w": ["250 per metre", "1/500 per metre", "0, since it is a circle"], "why": "Curve-bend technique: a circle of radius r bends by 1/r."}, {"q": "The bend of a curve is |T′(s)|. Which tracing does it ask for?", "a": "speed 1, with s the distance travelled", "w": ["any tracing at all", "speed 2, to see the turn twice", "the tracing by x"], "why": "A faster tracing makes the second slope larger without bending the curve more."}, {"q": "T · T = 1 along a speed-1 curve. What follows for T′?", "a": "T′ is at right angles to T", "w": ["T′ = 0", "T′ has length 1", "T′ points along T"], "why": "Moving-dot: the slope of T · T is 2T · T′, and the slope of 1 is 0."}, {"q": "[[L, M], [M, N]] with L = r<sub>uu</sub> · n and so on. What is it called here?", "a": "the bending grid", "w": ["the ruler grid", "the slope grid", "the main bend"], "why": "Accepted name: second fundamental form."}, {"q": "A speed-1 curve on a surface leaves in direction (u′, v′). How much does it bend toward n?", "a": "L u′² + 2M u′v′ + N v′²", "w": ["E u′² + 2F u′v′ + G v′²", "LN − M²", "|γ″| for any tracing"], "why": "Normal-bend technique: the r<sub>u</sub> and r<sub>v</sub> terms drop out against n."}, {"q": "z = x² + 3y² at the origin. What is K?", "a": "12", "w": ["4", "6", "−12"], "why": "L = 2, M = 0, N = 6, and the ruler grid is the identity there: K = LN − M² = 12."}, {"q": "z = xy at the origin. What kind of point is it?", "a": "a saddle, K = −1", "w": ["a bowl, K = 1", "a tube-like fold, K = 0", "a dome, K = 1"], "why": "Main bends 1 and −1: they bend opposite ways."}, {"q": "Why does a cylinder have K = 0, though it is curved?", "a": "one of its two main bends is 0", "w": ["n does not turn on it", "its ruler grid is not the identity", "its bending grid is 0"], "why": "K is the product of the main bends, −1 and 0."}, {"q": "K can be computed from E, F, G and their slopes alone. Which technique is that?", "a": "the remarkable technique", "w": ["the surface-bend technique", "the normal-bend technique", "the ruler-change technique"], "why": "Accepted name: Theorema Egregium (1827). It is what lets a creature in the surface find K."}, {"q": "ds² = du² + g² dv². What is K?", "a": "−g<sub>uu</sub>/g", "w": ["g<sub>uu</sub>/g", "−g<sub>u</sub>/g", "1/g²"], "why": "Straight-out technique, from the remarkable technique with E = 1, F = 0."}, {"q": "Why does every flat map of the earth stretch something?", "a": "the sphere has K = 1/R² and the flat sheet K = 0, so no piece shares a ruler", "w": ["the earth is not exactly round", "maps are drawn with straight lines", "the poles have no longitude"], "why": "Same ruler would force the same K, by the remarkable technique."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29f"]=[{"q": "What is the total bend of a sphere of radius 6371 km?", "a": "4π", "w": ["4π × 6371²", "4π/6371²", "2π"], "why": "Sphere-total: K = 1/R² times area 4πR²; R cancels."}, {"q": "A spun surface between u = a and u = b. What is its total bend?", "a": "−2π(ρ′(b) − ρ′(a))", "w": ["2π(ρ(b) − ρ(a))", "∫ρ du", "4π always"], "why": "Spun-total: K dA = −ρ″ du dv, and ρ′ undoes ρ″."}, {"q": "A smooth closed surface spun from a curve leaving and returning to the axis at right angles. What is its total bend?", "a": "4π", "w": ["0", "2π", "it depends on the curve's shape"], "why": "ρ′ goes from 1 to −1: −2π(−1 − 1) = 4π."}, {"q": "The doughnut ρ = 3 + cos u. Where is K negative?", "a": "on the inner half, round the hole", "w": ["on the outer half", "nowhere", "everywhere"], "why": "K = cos u/(3 + cos u) is negative where cos u < 0."}, {"q": "Total bend = 2π(V − E + F), when each triangle's total is its excess. Which technique?", "a": "the excess-count technique", "w": ["the hole-count technique", "the sphere-total technique", "the excess-area technique"], "why": "Sum the excesses: the angles round each corner make 2π, and 3F = 2E."}, {"q": "Each triangle has three edges and each edge sits in two triangles. What follows?", "a": "3F = 2E", "w": ["2F = 3E", "V = E − F", "F = E"], "why": "Count edge-sides two ways."}, {"q": "A closed surface with g holes. What is V − E + F?", "a": "2 − 2g", "w": ["2 + 2g", "2 − g", "g − 2"], "why": "Hole-count technique: each handle adds 6 edges and 4 faces."}, {"q": "What is the total bend of a two-holed pretzel?", "a": "−4π", "w": ["0", "−8π", "4π"], "why": "4π(1 − g) with g = 2."}, {"q": "Cut a sphere finer, from 8 triangles to 20. What happens to V − E + F?", "a": "it stays 2", "w": ["it grows", "it shrinks", "it becomes 0"], "why": "It equals the total bend over 2π, which no cutting changes."}, {"q": "A ball is squeezed into an egg, smoothly, with no tear. What happens to the total bend?", "a": "it stays 4π", "w": ["it grows where the egg is pinched", "it shrinks with the volume", "it becomes 0"], "why": "Only the ends' slopes enter the spun-total, and they stay 1 and −1."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29g"]=[{"q": "y makes ∫ L(x, y, y′) dx least with fixed ends. What must it obey?", "a": "d/dx(∂L/∂p) = ∂L/∂y", "w": ["∂L/∂y = 0", "∂L/∂p = 0", "d/dx L = 0"], "why": "Best-path technique, by nudging and parts."}, {"q": "Why must a nudge η have η(a) = η(b) = 0?", "a": "the ends are fixed, and that drops the edge terms of parts", "w": ["so that η has a continuous slope", "so that j(t) is a number", "so that L stays positive"], "why": "y + tη must have the same ends as y."}, {"q": "∫ h η dx = 0 for every nudge, with h continuous. What follows?", "a": "h = 0 everywhere", "w": ["h is constant", "h is 0 at one point", "nothing"], "why": "Where h ≠ 0 a bump nudge makes ∫ hη ≠ 0."}, {"q": "L = √(1 + p²). What best curves does the equation give?", "a": "straight lines", "w": ["circles", "parabolas", "the curve y = e<sup>x</sup>"], "why": "L<sub>y</sub> = 0, so y′/√(1 + y′²) is constant, so y′ is."}, {"q": "A path on a surface that obeys the best-path equation for its length. What is it called here?", "a": "a straightest path", "w": ["a main bend", "a chart", "a ruler line"], "why": "Accepted name: geodesic."}, {"q": "Is every straightest path the shortest way between its ends?", "a": "no: the long arc of a great circle is straightest and not shortest", "w": ["yes, always", "yes, on a sphere", "no straightest path is ever shortest"], "why": "The equation is asked of best curves; it does not make a curve best."}, {"q": "In ds² = du² + g² dv², which curves are straightest, traced as u = s?", "a": "the curves v = constant", "w": ["the curves u = constant", "every curve", "only the curve u = 0"], "why": "v′ = 0 and u″ = 0 satisfy both path equations."}, {"q": "Along a straightest path in ds² = du² + g² dv², how does the heading ψ change?", "a": "dψ = −g<sub>u</sub> dv", "w": ["dψ = g dv", "dψ = −g<sub>uu</sub> du", "dψ = 0"], "why": "Heading technique, from the first path equation."}, {"q": "A triangle of straightest paths: what is its total bend?", "a": "its excess, α + β + γ − π", "w": ["its area", "π", "0"], "why": "Triangle-bend technique, which pays back the trust of 29f."}, {"q": "Disc plane, K = −1, angles 60°, 45°, 30°. What is the area?", "a": "π/4", "w": ["3π/4", "π", "π/2"], "why": "−area = excess = 3π/4 − π."}, {"q": "The circle of latitude 45° N between two points. Is it the shortest way?", "a": "no: it turns along the surface, and the great circle is shorter", "w": ["yes, it is a circle", "yes, it keeps the same latitude", "only on the equator side"], "why": "It fails u″ = g g<sub>u</sub> v′²."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29h"]=[{"q": "A one-to-one map from a piece of a surface onto an open region of the plane, undone by a smooth patch with EG − F² > 0. What is it?", "a": "a chart", "w": ["a ruler", "a change of page", "a straightest path"], "why": "Accepted name: coordinate chart."}, {"q": "Why are latitude and longitude not a chart at the poles?", "a": "every longitude names the pole, and EG − F² = 0 there", "w": ["the poles are too cold", "the ruler grid is the identity there", "K = 0 there"], "why": "G = R² cos² φ = 0 at φ = ±90°."}, {"q": "How many pages does the two-charts technique use to cover the sphere?", "a": "two, each missing one pole", "w": ["one", "four", "six"], "why": "Projection from the north pole and from the south pole."}, {"q": "North page (X, Y) = (x, y)/(1 − z). Where does the south pole go?", "a": "(0, 0)", "w": ["(1, 0)", "nowhere", "(∞, ∞)"], "why": "(0, 0, −1) ↦ (0, 0)/2."}, {"q": "What is the change of page between the sphere's two charts?", "a": "(X, Y) ↦ (X, Y)/(X² + Y²)", "w": ["(X, Y) ↦ (−X, −Y)", "(X, Y) ↦ (X², Y²)", "(X, Y) ↦ (X, Y)"], "why": "Page-change technique; as a complex number, w ↦ 1/w̄."}, {"q": "The north page ruler is 4(dX² + dY²)/(1 + X² + Y²)². Which ruler differs from it by one sign?", "a": "the disc plane's", "w": ["the flat plane's", "the cylinder's", "the polar ruler"], "why": "The Disc Plane's is 4(dx² + dy²)/(1 − x² − y²)²."}, {"q": "Two pages overlap. How must their ruler grids match?", "a": "g on one is Jᵀ g J on the other", "w": ["they must be equal", "their determinants must be equal", "they need not match"], "why": "Ruler-change: J is the slope grid of the change of page."}, {"q": "Length, angle, area and surface bend come out the same on every page. Which technique?", "a": "the page-agree technique", "w": ["the two-charts technique", "the remarkable technique alone", "the ruler-angle technique"], "why": "Ruler-change for lengths and angles, det-product for areas, the remarkable technique for K."}, {"q": "A space covered by pages whose changes are undoable with undoable slope grids. Accepted name?", "a": "a manifold", "w": ["a sphere", "an atlas", "a transition map"], "why": "The pages make an atlas; the changes are transition maps."}, {"q": "Does a surface with a ruler need a space around it?", "a": "no: an atlas and a ruler give its lengths, angles, areas and bend", "w": ["yes, to define n", "yes, to define K", "only for curved surfaces"], "why": "The disc plane is one page and a ruler."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29i"]=[{"q": "In a triangle on the sphere of radius 1, cos a equals:", "a": "cos b cos c + sin b sin c cos A", "w": ["cos b cos c − sin b sin c cos A", "b² + c² − 2bc cos A", "sin b sin c + cos b cos c cos A"], "why": "The sphere-cosine technique (29i1)."}, {"q": "Why is cos a = B · C for corners B, C on the sphere of radius 1?", "a": "The angle-between technique (27i1), with |B| = |C| = 1", "w": ["The excess-area technique (29b3)", "The cross technique (27i3)", "The lines-always-meet technique (29b1)"], "why": "The side a is the angle at the centre between B and C."}, {"q": "b = c = π/3 and A = π/2 on the sphere of radius 1. The third side a is:", "a": "arccos ¼ ≈ 1.318", "w": ["π/3 · √2 ≈ 1.481", "π/2", "arccos ½ = π/3"], "why": "cos a = ¼ + ¾ · 0. The flat answer is longer."}, {"q": "With the pole as a corner, the side from the pole to a place at latitude φ is:", "a": "π/2 − φ", "w": ["φ", "π − φ", "π/2 + φ"], "why": "Latitude is measured up from the equator, the side down from the pole."}, {"q": "The great circle distance on a sphere of radius R has cos δ equal to:", "a": "sin φ₁ sin φ₂ + cos φ₁ cos φ₂ cos Δλ", "w": ["cos φ₁ cos φ₂ + sin φ₁ sin φ₂ cos Δλ", "sin φ₁ sin φ₂ − cos φ₁ cos φ₂ cos Δλ", "cos(φ₂ − φ₁) cos Δλ"], "why": "The great-circle technique (29i2): sides π/2 − φ, angle Δλ at the pole."}, {"q": "Vancouver to Tokyo on a sphere of radius 6371 km is about:", "a": "7500 km", "w": ["9900 km", "5600 km", "20 000 km"], "why": "δ ≈ 1.178 rad."}, {"q": "A great circle leaves latitude φ₁ at heading h. Its farthest north φₘ has:", "a": "cos φₘ = cos φ₁ sin h", "w": ["sin φₘ = sin φ₁ cos h", "cos φₘ = sin φ₁ cos h", "tan φₘ = tan φ₁ sin h"], "why": "The farthest-north technique (29i3), from the sphere-sine technique with a right angle at the top."}, {"q": "The sphere-sine technique says sin A divided by which is the same at every corner?", "a": "sin a, the sine of the side facing A", "w": ["a, the side facing A in km", "cos a", "the excess"], "why": "|det[A B C]| = sin A sin b sin c from every corner."}, {"q": "Two places on latitude 45° N, half way round the globe. Which way is shorter?", "a": "Over the pole: about 10 008 km", "w": ["Along the circle of latitude: about 14 153 km", "Both are the same length", "Along the equator"], "why": "The circle of latitude is not a great circle (29b5)."}, {"q": "For a small triangle on a large sphere, the sphere-cosine technique becomes:", "a": "The cosine-side technique of the flat plane (21h2)", "w": ["The sphere-sine technique", "The excess-area technique", "Pythagoras with the excess added"], "why": "cos x ≈ 1 − x²/2, sin x ≈ x, and drop terms of fourth order."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29j"]=[{"q": "In the disc plane, the length of the shortest path from p to q is:", "a": "d(p, q) = ln((1 + ρ)/(1 − ρ)), ρ = |q − p|/|1 − p̄q|", "w": ["|q − p|", "2|q − p|/(1 − |p|²)", "ln(|q|/|p|)"], "why": "The disc-shortest technique (29j1)."}, {"q": "Which step shows a path from 0 out to distance u in the disc plane is at least u long?", "a": "Curves straight out are shortest (29g2)", "w": ["The disc-moves technique (29c1)", "The many-parallels technique (29c3)", "The below-straight technique (29c4)"], "why": "From 0 the disc ruler is straight out, du² + g² dv² (29e5)."}, {"q": "d(0, 0.8) in the disc plane is:", "a": "ln 9 ≈ 2.197", "w": ["0.8", "ln 1.8 ≈ 0.588", "ln 4 ≈ 1.386"], "why": "(1 + 0.8)/(1 − 0.8) = 9."}, {"q": "The half-plane map sends the disc plane's centre 0 to:", "a": "i", "w": ["0", "1", "the floor"], "why": "w = i(1 + z)/(1 − z) at z = 0."}, {"q": "In the half-plane, the ruler length of a small step is:", "a": "|dw| / y", "w": ["|dw| · y", "|dw|", "2|dw|/(1 − |w|²)"], "why": "The half-plane technique (29j2): height is everything."}, {"q": "Up a ray in the half-plane from height 3 to height 12, the distance is:", "a": "ln 4", "w": ["9", "ln 9", "4"], "why": "d(iy₁, iy₂) = ln(y₂/y₁)."}, {"q": "The lines of the half-plane are:", "a": "Upright half-lines and half-circles centred on the floor", "w": ["All straight lines", "Circles through i", "Half-circles through 0"], "why": "Circles meeting the edge square go to circles meeting the floor square."}, {"q": "A disc-plane circle of radius ρ has length:", "a": "π(e^ρ − e^(−ρ))", "w": ["2πρ", "πρ²", "2π(e^ρ − 1)"], "why": "The disc-circle technique (29j3)."}, {"q": "A disc-plane triangle has angles π/2, π/8, π/8. Its area is:", "a": "π/4", "w": ["3π/4", "π/8", "0"], "why": "Triangle-total (29g4) with K = −1: area = π minus the angles."}, {"q": "In the half-plane, which is shorter from −1 + i to 1 + i?", "a": "The half-circle about 0: about 1.763", "w": ["The flat segment: 2", "They are equal", "Neither: there is no shortest path"], "why": "It climbs to where steps are cheaper."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29k"]=[{"q": "A curve traced at any speed with γ′ ≠ 0 has bend:", "a": "|γ′ × γ″| / |γ′|³", "w": ["|γ″|", "|γ′ × γ″| / |γ′|²", "|γ″| / |γ′|"], "why": "The any-speed-bend technique (29k1)."}, {"q": "In that proof, why does |T × dT/dt| equal |dT/dt|?", "a": "T has length 1, so it moves at right angles to itself (27i4)", "w": ["T × T = 0 (27i3)", "dT/dt = 0 at speed 1", "The chain technique (13)"], "why": "Vectors at right angles: the cross has the product of their sizes."}, {"q": "The helix (a cos t, a sin t, bt) bends by:", "a": "a/(a² + b²)", "w": ["1/a", "1/(a² + b²)", "b/(a² + b²)"], "why": "The climb straightens it."}, {"q": "The bend of y = x² at x = 1 is:", "a": "2/5^(3/2) ≈ 0.179", "w": ["2", "1/2", "2/5"], "why": "|f″|/(1 + f′²)^(3/2)."}, {"q": "The surface z = f(x, y) has surface bend:", "a": "(f_xx f_yy − f_xy²)/(1 + f_x² + f_y²)²", "w": ["f_xx f_yy − f_xy²", "(f_xx f_yy − f_xy²)/(1 + f_x² + f_y²)", "f_xx + f_yy"], "why": "The graph-bend technique (29k2)."}, {"q": "The saddle z = xy has K at (1, 1) equal to:", "a": "−1/9", "w": ["−1", "1/9", "0"], "why": "−1/(1 + x² + y²)²."}, {"q": "On a spun surface, the main bend around the axis is:", "a": "z′/ρ", "w": ["1/ρ", "ρ″", "−ρ″/ρ"], "why": "The spun-bends technique (29k3)."}, {"q": "On a bagel spun from a circle of radius 2 about a centre 4 from the axis, K on the inside is:", "a": "−1/4", "w": ["1/12", "0", "1/8"], "why": "Bends 1/2 and −1/2."}, {"q": "At the top circle of a doughnut, K is:", "a": "0", "w": ["1/a²", "1/(aR)", "−1/a²"], "why": "z′ = 0 there, so the bend around the axis is 0."}, {"q": "A surface with K = 0 at every point must be part of a plane?", "a": "No: a cylinder and a cone have K = 0", "w": ["Yes, by the remarkable technique", "Yes, by the graph-bend technique", "Only if it is closed"], "why": "One main bend can be 0 while the other is not."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29l"]=[{"q": "If L depends on y and p only, along a solution of the best-path equation what keeps one value?", "a": "L − y′L_p", "w": ["L + y′L_p", "L_p", "L − y L_y"], "why": "The no-x technique (29l1)."}, {"q": "Which step licenses d/dx L(y, y′) = L_y y′ + L_p y″?", "a": "The roads-add technique (28c3)", "w": ["The best-path technique (29g1)", "The no-x technique (29l1)", "The lines-up technique (28g2)"], "why": "Two roads into L: through y and through p = y′."}, {"q": "A bead slides from rest down a wire, y measured down. Its speed after dropping y is:", "a": "√(2gy)", "w": ["2gy", "gy", "√(gy)"], "why": "mgy of work becomes ½mv²."}, {"q": "The fastest slide obeys:", "a": "y(1 + y′²) = 2r", "w": ["y′ = constant", "y = c C(x/c)", "y″ = g"], "why": "The no-x technique on √(1 + p²)/√(2gy)."}, {"q": "The Fastest Slide's curve is traced by:", "a": "a point on the rim of a rolling wheel", "w": ["a hanging chain", "a quarter circle", "a parabola thrown from the start"], "why": "x = r(θ − sin θ), y = r(1 − cos θ)."}, {"q": "On the wheel's curve, the time to the point at θ is:", "a": "θ√(a/g)", "w": ["θ√(g/a)", "√(2θa/g)", "π√(a/g) at every point"], "why": "dt = ds/v = √(a/g) dθ."}, {"q": "For the slide from (0, 0) to (10π, 20) m, the wheel's curve beats the straight chute by about:", "a": "0.6 s", "w": ["0.06 s", "2 s", "nothing: the chute is faster"], "why": "3.17 s against 3.76 s."}, {"q": "A soap film between two rings, least in area, has profile:", "a": "y = c C((x − b)/c)", "w": ["a parabola", "a circle", "a straight line"], "why": "The soap-film technique (29l3): y/√(1 + y′²) = a."}, {"q": "Rings of radius 10 cm: beyond about what distance apart is there no film curve?", "a": "13.25 cm", "w": ["10 cm", "20 cm", "6.6 cm"], "why": "u/C(u) is at most about 0.6627."}, {"q": "The hanging chain needs which step held in trust?", "a": "The lines-up technique carried over to paths", "w": ["The best-path technique (29g1)", "The no-x technique (29l1)", "The put-back technique (24f2)"], "why": "Least height total among curves of one length: a constraint."}, {"q": "Two curves through the same rings obey the soap-film equation. Which is least?", "a": "The deeper one, a ≈ 8.48, 599 cm²", "w": ["The shallow one, a ≈ 2.35, 685 cm²", "Both, since both obey the equation", "Neither: two flat discs always win"], "why": "The equation is asked of least curves; it does not make one least."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29m"]=[{"q": "The window z = 1 paints X = (x, y, z), z > 0, at:", "a": "(x/z, y/z)", "w": ["(x, y)", "(z/x, z/y)", "(x − z, y − z)"], "why": "Where the line from the eye to X crosses the window."}, {"q": "Lines along v with v₃ > 0 are painted running to:", "a": "(v₁/v₃, v₂/v₃)", "w": ["(v₁, v₂)", "(0, 0) always", "(v₃/v₁, v₃/v₂)"], "why": "The vanishing-point technique (29m1)."}, {"q": "Where do the vanishing points of level lines lie, for a level eye?", "a": "On the horizon, at eye height", "w": ["At the bottom of the picture", "Nowhere: level lines stay parallel", "At the centre only"], "why": "v₂ = 0 gives (v₁/v₃, 0)."}, {"q": "Which step licenses n · X(t) = 0 for n = P × v and X(t) = P + tv?", "a": "The cross technique (27i3)", "w": ["The angle-between technique (27i1)", "The four-number technique (25f4)", "The lines-always-meet technique (29b1)"], "why": "The cross is at right angles to P and to v."}, {"q": "Two different lines [a] and [b] meet at:", "a": "[a × b]", "w": ["[a + b]", "[a · b]", "nowhere, if parallel"], "why": "The meet-by-cross technique (29m2)."}, {"q": "u − w = 0 and u − w + 1 = 0 meet at:", "a": "[1 : 1 : 0], the point at infinity along (1, 1)", "w": ["They never meet", "[1 : −1 : 0]", "(0, 0)"], "why": "(1, −1, 0) × (1, −1, 1) = (−1, −1, 0)."}, {"q": "The line at infinity is:", "a": "[0 : 0 : 1]", "w": ["[1 : 1 : 1]", "[0 : 0 : 0]", "[1 : 0 : 0]"], "why": "The plane z = 0 through the eye."}, {"q": "[1 : −1 : 0] and [−1 : 1 : 0] are:", "a": "The same point", "w": ["Two points at infinity, one at each end", "Two lines", "Not points"], "why": "Multiples name the same point."}, {"q": "A painter's move keeps which number of four points on a line?", "a": "(t₁ − t₃)(t₂ − t₄)/((t₂ − t₃)(t₁ − t₄))", "w": ["(t₁ − t₂)/(t₂ − t₃)", "t₄ − t₁", "(t₁ + t₂)/(t₃ + t₄)"], "why": "The four-point-ratio technique (29m3)."}, {"q": "Four equally spaced posts have four-point ratio:", "a": "4/3", "w": ["1", "3", "2"], "why": "(0 − 2)(1 − 3)/((1 − 2)(0 − 3))."}, {"q": "Is the picture of a midpoint the midpoint of the picture?", "a": "No: sleepers at 2, 4, 6 m give −0.8, −0.4, −0.267", "w": ["Yes, painter's moves keep midpoints", "Yes, for level lines", "Only on the horizon"], "why": "The picture map is a four-number map, not a straight map."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29·cb3"]=[{"q": "A transitive set whose different members are lined up by membership is called …", "a": "a point of the run", "w": ["an inductive set", "a layer", "a well-order"], "why": "29·cb3.1’s definition; every number and ω are points."}, {"q": "ℕ, read as a point of the run, is written …", "a": "ω", "w": ["S(ℕ)", "V_ω", "ω + 1"], "why": "29·cb3.1 names it."}, {"q": "ω + 1 is …", "a": "ω ∪ {ω}", "w": ["ω ∪ {1}", "{ω}", "ω with 0 taken out"], "why": "The one-past technique: the next one after ω."}, {"q": "ℕ lined up as 1, 2, 3, …, 0. Its shape is that of …", "a": "ω + 1", "w": ["ω", "1 + ω", "ω + ω"], "why": "It has a last member, 0; ω has none."}, {"q": "ℕ lined up as 0, 2, 4, …, 1, 3, 5, …. Its shape is that of …", "a": "ω + ω", "w": ["ω", "ω + 2", "ω + 1"], "why": "Two endless runs, one after the other."}, {"q": "In the world past the run, which is missing?", "a": "ω + ω", "w": ["ω", "ω + 5", "𝒫(ω)"], "why": "The short-world technique: each ω + k is in a layer, their gathering is not."}, {"q": "Which line gathers {ω + n : n ∈ ω} into a set?", "a": "the doubled-run technique", "w": ["the one-past technique", "Sift", "Power"], "why": "It applies Replace to the pairing n ↦ ω + n; Sift needs a set to sift from."}, {"q": "“When a pairing hands each member of a set exactly one thing, the things handed form a set.” This is …", "a": "the axiom Replace", "w": ["the axiom Sift", "the infinity axiom", "the recursion technique"], "why": "29·cb3.3 lays it down; accepted name: replacement."}, {"q": "The condition “y ∈ x” on the set {1, 2}. Is it a pairing on that set?", "a": "no: 2 hands two things", "w": ["yes", "yes, since each x has a member", "no: 1 hands nothing"], "why": "A pairing gives exactly one y for each x; 2 = {0, 1}."}, {"q": "ω + 2 ∋ ω + 1 ∋ ω ∋ 10⁶ ∋ …. Must this fall stop?", "a": "yes, after some number of steps", "w": ["no, it can go on for ever", "only if it starts below ω", "only if each step drops by one"], "why": "The falling-run technique: a bottom member ends every fall."}, {"q": "The two-digit game from 99 in base 10 climbs to 5119. Why does it still end?", "a": "its label ω·d + c falls at every turn", "w": ["the base stops growing", "the number falls at every turn", "the top digit falls at every turn"], "why": "The base-bump technique, with the falling-run technique."}, {"q": "“1 + ω = ω + 1.” What is wrong?", "a": "one in front gives ω; one behind gives a last member", "w": ["both are ω", "neither is a point", "1 + ω is not a set"], "why": "29·cb3.1: order matters past the run."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["29·cb28"]=[{"q": "dx dy reads two vectors u, v. It gives …", "a": "u₁v₂ − u₂v₁", "w": ["u₁v₁ + u₂v₂", "u₁v₂ + u₂v₁", "u₁u₂ − v₁v₂"], "why": "The two-vector technique: a determinant."}, {"q": "dy dx equals …", "a": "−dx dy", "w": ["dx dy", "0", "dy dy"], "why": "Swapping the rows of a determinant turns its sign."}, {"q": "dx dx equals …", "a": "0", "w": ["dx²", "2 dx", "1"], "why": "A determinant with two equal rows is 0."}, {"q": "A thing that reads k vectors, adds in each and turns sign on a swap, is called …", "a": "a form of degree k", "w": ["a field", "a ruler", "a patch"], "why": "29·cb28.1’s academy word."}, {"q": "d(P dx + Q dy + R dz) has dx dy part …", "a": "(Q_x − P_y) dx dy", "w": ["(P_x + Q_y) dx dy", "(P_y − Q_x) dx dy", "(R_z) dx dy"], "why": "The one-slope technique: the swirl vector’s third entry."}, {"q": "d(A dy dz + B dz dx + C dx dy) is …", "a": "(A_x + B_y + C_z) dx dy dz", "w": ["(A_x − B_y + C_z) dx dy dz", "the swirl vector of (A, B, C)", "0 always"], "why": "The one-slope technique: the spread."}, {"q": "Why is d(df) = 0?", "a": "the mixed second slopes agree", "w": ["df is 0", "d is straight", "the edge of an edge is nothing"], "why": "The twice-nothing technique, by the swap-knobs technique (28d)."}, {"q": "Which is the twice-nothing technique, read on fields?", "a": "a swirl vector has no spread", "w": ["an uphill field has no spread", "a swirl vector has no swirl", "every field is uphill"], "why": "d(dω) = 0 for a form of degree 1."}, {"q": "∫ over the edge of M of ω = ∫ over M of dω, on a rectangle with ω = P dx + Q dy, is …", "a": "28j’s swirl technique", "w": ["28j’s spread technique", "the uphill-total technique", "the cross-slopes technique"], "why": "The boundary technique in degree 1 on a rectangle."}, {"q": "Circulation round the edge of a curved patch equals …", "a": "the flux of the swirl vector through it", "w": ["the spread inside it", "the area of the patch", "0 always"], "why": "The curved-swirl technique."}, {"q": "ω = (−y dx + x dy)/(x² + y²) has dω = 0 off 0, and total 2π round the unit circle. What follows?", "a": "the circle bounds no patch missing 0", "w": ["the swirl technique is false", "ω is d of a function there", "the total should be 0"], "why": "The hole-test technique."}, {"q": "“dω = 0, so ω = dg.” When does this fail?", "a": "on a region with a hole", "w": ["never", "when ω is of degree 1", "when the box is small"], "why": "The wire’s form is d of nothing round the wire."}];
